// ───────── Construction des dictionnaires par langue
export function buildDictionaries() {
  const dicts = Object.fromEntries(CODES.map((c) => [c, {}]));
  for (const row of ROWS) {
    const key = row[0];
    CODES.forEach((code, i) => {
      if (row[i]) dicts[code][key] = row[i]; // colonne vide = pas de traduction (langue de repli)
    });
  }
  return dicts;
}
